package schema

import (
	"time"

	"entgo.io/ent"
	"entgo.io/ent/schema/field"
	"entgo.io/ent/schema/index"
)

// Alert holds the schema definition for the Alert entity generated by the R Random Forest pipeline.
type Alert struct {
	ent.Schema
}

// Fields of the Alert.
func (Alert) Fields() []ent.Field {
	return []ent.Field{
		field.String("id").
			NotEmpty().
			Unique().
			Comment("Composite ID: {state}|{lga}|{month}"),
		field.String("state").
			NotEmpty(),
		field.String("lga").
			NotEmpty(),
		field.String("month").
			NotEmpty().
			Comment("Month in YYYY-MM format"),
		field.Int("n_records").
			Default(0),
		field.Float("mean_risk").
			Comment("Predicted probability of high malaria vector risk [0.0 - 1.0]"),
		field.Float("mean_pyrethroid_mort").
			Optional().
			Nillable().
			Comment("Mean pyrethroid mortality percentage"),
		field.String("tier").
			NotEmpty().
			Comment("ALERT (>=0.70), WARNING (0.50-0.69), WATCH (<0.50)"),
		field.Bool("pyrethroid_resistance_flag").
			Default(false).
			Comment("Flag indicating pyrethroid resistance"),
		field.Bool("acknowledged").
			Default(false),
		field.String("acknowledged_by").
			Optional().
			Nillable(),
		field.Time("acknowledged_at").
			Optional().
			Nillable(),
		field.String("acknowledgement_note").
			Optional().
			Nillable(),
		field.Time("created_at").
			Default(time.Now).
			Immutable(),
		field.Time("updated_at").
			Default(time.Now).
			UpdateDefault(time.Now),
	}
}

// Indexes of the Alert.
func (Alert) Indexes() []ent.Index {
	return []ent.Index{
		index.Fields("state", "lga"),
		index.Fields("month"),
		index.Fields("tier"),
	}
}
